import type { L } from '@/i18n'

/**
 * Gabush characters. Images are generated by `npm run characters` from public/images/animals
 * (open/closed-eye pair → transparent WebP at 480 and 800 px wide, identical except the eyes).
 * To show another character, pass its id to <BlinkingCharacter id="…" />.
 */
export type CharacterId = 'leon' | 'elefante' | 'tigre' | 'conejo' | 'oso' | 'buho'

export interface Character {
  name: L
  /** intrinsic size of the 800 px image (keeps the layout from shifting) */
  width: number
  height: number
}

export const CHARACTERS: Record<CharacterId, Character> = {
  leon: { name: { es: 'León Gabush', en: 'Gabush the lion' }, width: 800, height: 1017 },
  elefante: { name: { es: 'Elefante Gabush', en: 'Gabush elephant' }, width: 800, height: 955 },
  tigre: { name: { es: 'Tigre Gabush', en: 'Gabush tiger' }, width: 800, height: 1058 },
  conejo: { name: { es: 'Conejo Gabush', en: 'Gabush rabbit' }, width: 800, height: 1248 },
  oso: { name: { es: 'Oso Gabush', en: 'Gabush bear' }, width: 800, height: 1047 },
  buho: { name: { es: 'Búho Gabush', en: 'Gabush owl' }, width: 800, height: 825 },
}

export const characterSrc = (id: CharacterId, frame: 'open' | 'closed') => ({
  src: `/images/characters/${id}-${frame}-800.webp`,
  srcSet: `/images/characters/${id}-${frame}-480.webp 480w, /images/characters/${id}-${frame}-800.webp 800w`,
})
